   563→        public BlockHeader? FindHeader(Hash256? blockHash, BlockTreeLookupOptions options, long? blockNumber = null)
   564→        {
   565→            if (blockHash is null || blockHash == Keccak.Zero)
   566→            {
   567→                // TODO: would be great to check why this is still needed (maybe it is something archaic)
   568→                return null;
   569→            }
   570→
   571→            BlockHeader? header = _headerStore.Get(blockHash, shouldCache: false, blockNumber: blockNumber);
   572→            if (header is null)
   573→            {
   574→                bool allowInvalid = (options & BlockTreeLookupOptions.AllowInvalid) == BlockTreeLookupOptions.AllowInvalid;
   575→                if (allowInvalid && _invalidBlocks.TryGet(blockHash, out Block block))
   576→                {
   577→                    header = block.Header;
   578→                }
   579→
   580→                return header;
